def add_grad(left, right):
  """Recursively add the gradient of two objects.

  Args:
    left: The left value to add. Can be either an array, a number, list or
        dictionary.
    right: The right value. Must be of the same type (recursively) as the left.

  Returns:
    The sum of the two gradients, which will of the same type.
  """
    import numbers, collections.abc
    try:
        import numpy as _np
    except Exception:
        _np = None

    # Helper to identify numeric types (including numpy scalars)
    def _is_number(x):
        return isinstance(x, numbers.Number) or (_np is not None and isinstance(x, _np.generic))

    # Main recursive addition
    if isinstance(left, dict) and isinstance(right, dict):
        if left.keys() != right.keys():
            raise TypeError("Dictionary keys must match for addition")
        return {k: add_grad(left[k], right[k]) for k in left}
