def _np_dtype(bit_res, discrete):
    """
    Given the bit resolution of a signal, return the minimum numpy dtype
    used to store it.

    Parameters
    ----------
    bit_res : int
        The bit resolution.
    discrete : bool
        Whether the dtype is to be int or float.

    Returns
    -------
    dtype : str
        String numpy dtype used to store the signal of the given
        resolution

    """
    if not isinstance(bit_res, int) or bit_res <= 0:
        raise ValueError("bit_res must be a positive integer")
    if discrete:
        if bit_res <= 8:
            return 'uint8'
        elif bit_res <= 16:
            return 'uint16'
        elif bit_res <= 32:
            return 'uint32'
        elif bit_res <= 64:
            return 'uint64'
        else:
            raise ValueError("bit_res too large for available integer dtypes")
    else:
        # mantissa bits: float16≈11, float32≈24, float64≈53
        if bit_res <= 11:
            return 'float16'
        elif bit_res <= 24:
            return 'float32'
        elif bit_res <= 53:
            return '

