def _call_connection_lost_and_clean_up(self, exc):
        """
        Clean up all resources and call the protocols connection lost method.
        """
        if getattr(self, "_connection_lost", False):
            return
        self._connection_lost = True

        # Cancel any pending futures (e.g., reads/writes)
        pending = getattr(self, "_pending_futures", None)
        if pending:
            for fut in list(pending):
                if not fut.done():
                    fut.cancel()
            pending.clear()

        # Close the underlying socket if present
        sock = getattr(self, "_socket", None)
        if sock is not None:
            try:
                sock.close()
            except Exception:
                pass

        # Notify the protocol, if any
        protocol = getattr(self, "_protocol", None)
        if protocol is not None:
            try:
                protocol.connection_lost(exc)
            except Exception

