def register(self, model_or_iterable, opts_class=None, **options):
        """
        Registers the given model(s) with the given translation options.

        The model(s) should be Model classes, not instances.

        Fields declared for translation on a base class are inherited by
        subclasses. If the model or one of its subclasses is already
        registered for translation, this will raise an exception.
        """
        # Ensure we have a registry dict
        if not hasattr(self, "_registry"):
            self._registry = {}
        # Determine iterable of models
        if isinstance(model_or_iterable, type):
            models = [model_or_iterable]
        else:
            try:
                # strings are not valid model classes, treat them as non‑iterable
                if isinstance(model_or_iterable, (str, bytes)):
