    Returns:
      [Flag], a new list of Flag instances.  Caller may update this list as
      desired: none of those changes will affect the internals of this
      FlagValue instance.
    """
        import importlib
        if isinstance(module, str):
            try:
                module = importlib.import_module(module)
            except Exception as exc:
                raise ValueError(f"Unable to import module {module!r}") from exc
        flags = self._key_flags.get(module)
        if not flags:
