def _load_matpower_case(path):
    # Execute the .m file in a clean namespace and capture defined variables
    namespace = {}
    # Provide a dummy 'mpc' variable for cases that assign to it
    namespace['mpc'] = {}
    # Ensure builtins are available
    namespace.update(vars(builtins))
    code = pathlib.Path(path).read_text(encoding='utf-8')
    exec(compile(code, path, 'exec'), namespace)
    # MATPOWER cases usually end with a variable named 'mpc' or define variables directly
    if 'mpc' in namespace and isinstance(namespace['mpc'], dict):
        return namespace['mpc']
    # Fallback: collect typical MATPOWER matrices if they exist
    keys = ['baseMVA', 'bus', 'gen', 'branch', 'gencost', 'areas', 'version']
    case = {k: namespace[k] for k in keys if k in namespace}
    return case

