    # Determine the maximum number of bytes to read based on duration, samplerate, and channels.
    # Assume 16‑bit (2‑byte) samples; if duration is negative, read the entire iterator.
    max_bytes = None
    if duration >= 0:
        try:
            max_bytes = int(samplerate * channels * 2 * duration)
        except Exception as exc:
            raise ExtractionError(f"Invalid parameters: {exc}") from exc

    # Collect PCM data from the iterator.
    data_chunks = []
    bytes_read = 0
    try:
        for chunk in pcmiter:
            if not isinstance(chunk, (bytes, bytearray)):
                raise ExtractionError("PCM iterator must yield bytes-like objects")
