def cursor(self, query, *args, prefetch=None, timeout=None):
        """Return a *cursor factory* for the specified query.

        :param args: Query arguments.
        :param int prefetch: The number of rows the *cursor iterator*
                             will prefetch (defaults to ``50``.)
        :param float timeout: Optional timeout in seconds.

        :return: A :class:`~cursor.CursorFactory` object.
        """
        if prefetch is None:
            prefetch = 50
        else:
            try:
                prefetch = int(prefetch)
            except Exception as exc:
                raise TypeError("prefetch must be an integer") from exc
            if prefetch <= 0:
                raise ValueError("prefetch must be a positive integer")
        if timeout is not None:
            try:
                timeout = float(timeout)
            except Exception as exc:
                raise TypeError("timeout must be a number") from exc
            if timeout < 0:
                raise ValueError("timeout must be non‑negative")
        from .cursor import CursorFactory
        return CursorFactory(self, query, args, prefetch=prefetch

