        else:
            formatted = '{0:0{1}d}s'.format(final_seconds, 2 if leading_zero else 1)
        return formatted

    # Determine which string template to use.
    if final_weeks:
        template = '{0:d}w {1:d}d {2:d}h {3:02d}m {4:02d}s' if leading_zero else '{0}w {1}d {2}h {3}m {4}s'
