def _restore_volume(self, fade):
        """Reinstate volume.

        Args:
            fade (bool): Whether volume should be faded up on restore.
        """
        # Retrieve the previously saved volume; if none, nothing to restore.
        saved = getattr(self, "_saved_volume", None)
        if saved is None:
            return

        # If a fade‑in is requested, gradually increase the volume.
        if fade:
            # Determine fade parameters; allow class overrides.
            steps = getattr(self, "_fade_steps", 20)
            total_time = getattr(self, "_fade_duration", 0.5)  # seconds
            if steps <= 0:
                steps = 1
            step_delay = total_time / steps
            # Compute incremental change per step.
